  async function retryUpload(localId: string) {
    if (activeId.value === null) return
    staged.value = markRetrying(staged.value, localId)
    await uploadFile(localId, activeId.value)
  }

  async function send(text?: string) {
    const content = (text ?? draft.value).trim()
    const ready = staged.value
    if (!canSendMessage(content, ready, busy.value) || activeId.value === null) return
    const conversationId = activeId.value
    const tempId = -(++tempSeq)
    const attachmentIds = uploadedIds(ready)
    const attachments = ready.flatMap(f => (f.attachment ? [f.attachment] : []))
    clearFeedback()
    attachmentErrors.value = []
    messages.value = mergeMessages(messages.value, [optimisticMessage(tempId, content, new Date(), attachments)])
    draft.value = ''
    staged.value = [] // moved into the message; restored below if the send fails
    sending.value = true
    try {
      const turn = await api<TurnResponse>(`/api/chat/conversations/${conversationId}/messages`, {
        method: 'POST',
        body: attachmentIds.length ? { content, attachment_ids: attachmentIds } : { content },
      })
      for (const item of ready) revokePreview(item)
      upsert(turn.conversation)
      if (activeId.value !== conversationId) return
      messages.value = reconcileCards(applyTurn(messages.value, tempId, turn), { hasPendingCard: turn.conversation.has_pending_card })
      warning.value = warningMessage(turn.warning_code)
    }
    catch (cause) {
      if (activeId.value !== conversationId) {
        for (const item of ready) revokePreview(item)
        return
      }
      messages.value = messages.value.filter(m => m.id !== tempId)
      if (!draft.value) draft.value = content // keep the text so nothing is lost
      if (!staged.value.length) staged.value = ready // and the files
      else for (const item of ready) revokePreview(item)
      fail(cause, 'send', () => send())
    }
    finally {
      sending.value = false
    }
  }
  }

  function dismissNotice() {
    notice.value = null
  }

  function dismissError() {
    error.value = null
  }

  /** Re-runs the failed step (send, card action or load). */
  async function retry() {
    const step = error.value?.retry
    if (!step) return
    error.value = null
    await step()
  }

  return {
    conversations,
    activeId,
}

/* ---- Errors ---- */

export type ChatAction = 'load' | 'send' | 'card'

/** User-facing message for a chat API failure (never echoes server text). `status` undefined = network error. */
export function chatErrorMessage(status: number | undefined, action: ChatAction): string {
  if (status === undefined) return 'Cannot reach the server. Check your connection and try again.'
  if (status === 403) return 'The chat is available to employees only.'
  if (status === 404) return 'That conversation could not be found.'
  if (status === 409) return 'That card is out of date.'
  if (status === 422) return action === 'send' ? 'That message could not be sent. Keep it between 1 and 1000 characters.' : 'That request was not accepted.'
  if (status === 429) return 'Too many requests. Please wait a moment and try again.'
  if (status >= 500) return 'The server had a problem. Please try again in a moment.'
  return 'Something went wrong. Please try again.'
}

const WARNING_MESSAGES: Readonly<Record<WarningCode, string>> = {
  llm_unavailable: 'The AI service is unavailable, please try again.',
  llm_invalid_output: 'The AI gave an answer I could not use. Please rephrase and try again.',
  submission_failed: 'The submission to ReqRes failed. Your request is saved; use Retry on the card to try again.',
  stale_card: 'That card is out of date.',
}

/** Banner text for a `warning_code`; null when there is nothing to show (or an unknown code). */
export function warningMessage(code: string | null | undefined): string | null {
  if (!code) return null
  return (WARNING_MESSAGES as Record<string, string | undefined>)[code] ?? 'Something needs your attention. Please try again.'
}
<script setup lang="ts">
import type { InboxAction, Message } from '~/types/chat'

const props = defineProps<{
  conversationId: number | null
  messages: Message[]
  loading: boolean
  sending: boolean
  acting: { cardId: string, decision: 'confirm' | 'discard' } | null
  busy: boolean
  /** The user may file requests: show the filing suggestions in the empty state. Otherwise a lighter inbox hint. */
  canRequest: boolean
  activeInboxId: string | null
  inboxActing: { cardId: string, action: InboxAction } | null
  inboxError: { cardId: string, action: InboxAction, text: string } | null
}>()
const emit = defineEmits<{
  action: [cardId: string, decision: 'confirm' | 'discard']
  inbox: [cardId: string, action: InboxAction, note: string | null]
  suggest: [text: string]
}>()

const scroller = ref<HTMLElement | null>(null)
/** True while the view follows new messages; turns false as soon as the user scrolls up. */
const following = ref(true)
const announcement = ref('')

// Instant (not smooth) on purpose: a smooth scroll fires scroll events that would look like the user scrolling up.
function scrollToBottom() {
  const el = scroller.value
  if (el) el.scrollTop = el.scrollHeight
}

function onScroll() {
  const el = scroller.value
  if (el) following.value = isNearBottom(el)
}

function jumpToLatest() {
  following.value = true
  scrollToBottom()
}

// A different conversation: start at the bottom and stay silent (only NEW assistant messages are announced).
watch(() => props.conversationId, () => {
  following.value = true
  announcement.value = ''
})

// Messages that are on screen when a conversation finishes loading are not "new".
let announcedUpTo = 0
watch(() => props.loading, (loading) => {
  if (!loading) announcedUpTo = props.messages.reduce((max, m) => Math.max(max, m.id), 0)
}, { immediate: true })

watch(() => props.messages, async (list, previous) => {
  if (props.loading) return
  const fresh = list.filter(m => m.sender_type === 'assistant' && m.id > announcedUpTo)
  if (fresh.length && previous.length) {
    announcement.value = fresh.map(announcementFor).join(' ')
  }
  announcedUpTo = Math.max(announcedUpTo, ...list.map(m => m.id))
  // Own message: always show it. Otherwise only follow when the user has not scrolled up.
  if (lastMessageIsUser(list)) following.value = true
  await nextTick()
  if (following.value) scrollToBottom()
})

watch(() => [props.loading, props.sending, props.acting], async () => {
  await nextTick()
  if (following.value) scrollToBottom()
})

const isEmpty = computed(() => !props.loading && props.messages.length === 0)
</script>

<template>
  <div class="relative min-h-0 flex-1">
    <div
      ref="scroller"
      class="h-full overflow-y-auto overscroll-contain px-3 py-4 sm:px-5"
      tabindex="0"
      role="region"
      aria-label="Conversation messages"
      @scroll.passive="onScroll"
    >
      <div v-if="loading" class="flex h-full items-center justify-center gap-2 text-sm" role="status">
        <IconGlyph name="spinner" class="h-4 w-4" />
        Loading conversation...
      </div>

      <div v-else-if="isEmpty && !canRequest" class="mx-auto flex h-full max-w-xl flex-col items-center justify-center gap-3 py-6 text-center">
        <span class="flex h-12 w-12 items-center justify-center rounded-full border border-secondary/40" aria-hidden="true">
          <IconGlyph name="inbox" class="h-6 w-6" />
        </span>
        <h2 class="text-lg font-semibold">
          Your inbox is empty here
        </h2>
        <p class="text-sm opacity-90">
          Use the bell to see what needs your attention. You can also ask me a question below, for example about the status of a request.
        </p>
      </div>

      <div v-else-if="isEmpty" class="mx-auto flex h-full max-w-xl flex-col items-center justify-center gap-4 py-6 text-center">
        <span class="flex h-12 w-12 items-center justify-center rounded-full border border-secondary/40" aria-hidden="true">
          <IconGlyph name="chat" class="h-6 w-6" />
        </span>
        <div>
          <h2 class="text-lg font-semibold">
            How can I help today?
          </h2>
          <p class="mt-1 text-sm opacity-90">
            Tell me in your own words about a leave application or a staff claim. I will ask for anything missing
            and show a card to confirm before anything is submitted.
          </p>
        </div>
        <SuggestionChips :disabled="busy" @pick="text => emit('suggest', text)" />
      </div>

      <ol v-else class="mx-auto flex max-w-3xl flex-col gap-4" aria-label="Messages">

