// Shared constants for the e2e suite: ports, paths and the environment of the API under test.
// Plain .mjs on purpose: the server launcher scripts run it with bare `node`.
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const here = path.dirname(fileURLToPath(import.meta.url))

export const E2E_DIR = path.resolve(here, '..')
export const REPO_DIR = path.resolve(E2E_DIR, '..')
export const BACKEND_DIR = path.join(REPO_DIR, 'backend')
export const FRONTEND_DIR = path.join(REPO_DIR, 'frontend')

// 9280/9281 never clash with Docker (9180/9181) or other dev servers (9190/9191/9199).
export const WEB_PORT = 9280
export const API_PORT = 9281
// `localhost` everywhere: the session cookie is host-scoped and must be shared by both ports.
export const WEB_URL = `http://localhost:${WEB_PORT}`
export const API_URL = `http://localhost:${API_PORT}`

export const TMP_DIR = path.join(E2E_DIR, '.tmp') // wiped on every run
export const DB_PATH = path.join(TMP_DIR, 'e2e.db')
export const UPLOAD_DIR = path.join(TMP_DIR, 'uploads')
export const BUILD_DIR = path.join(E2E_DIR, '.build', 'web') // kept between runs (incremental)

/**
 * Environment of the backend under test. Explicit variables beat the repo `.env`, so a real key
 * can never be used: the LLM and submission providers are the offline fakes and every key is empty.
 */
export function backendEnv() {
  return {
    ...process.env,
    APP_ENV: 'development',
    DATABASE_URL: `sqlite:///${DB_PATH}`,
    UPLOAD_DIR,
    LLM_PROVIDER: 'fake',
    LLM_FALLBACK_PROVIDER: '',
    SUBMISSION_PROVIDER: 'fake',
    JWT_SECRET_KEY: 'e2e-test-secret-not-for-production-0123456789',
    CORS_ORIGINS: WEB_URL,
    MOCK_SSO_ENABLED: 'true',
    DB_AUTO_SEED: 'true',
    GEMINI_API_KEY: '',
    REQRES_API_KEY: '',
    OLLAMA_BASE_URL: 'http://127.0.0.1:9', // nothing listens there: no accidental local model
  }
}

export function webEnv() {
  return {
    ...process.env,
    NITRO_PORT: String(WEB_PORT),
    NITRO_HOST: '127.0.0.1',
    NUXT_PUBLIC_API_BASE: API_URL,
    NUXT_API_BASE_SERVER: API_URL,
  }
}
EOF
cat > support/launch.mjs <<'EOF'
// Small helpers for the server launcher scripts (start-api.mjs, start-web.mjs).
import { spawn } from 'node:child_process'
import net from 'node:net'

/** True when something already accepts connections on `port` (IPv4 or IPv6 loopback). */
function accepts(port, host) {
  return new Promise((resolve) => {
    const socket = net.connect({ port, host })
    socket.once('connect', () => { socket.destroy(); resolve(true) })
    socket.once('error', () => resolve(false))
    socket.setTimeout(1000, () => { socket.destroy(); resolve(false) })
  })
}

export async function assertPortFree(port, what) {
  if ((await accepts(port, '127.0.0.1')) || (await accepts(port, '::1'))) {
    console.error(
      `\n[e2e] Port ${port} (${what}) is already in use.\n` +
      `      Stop whatever listens there (lsof -iTCP:${port} -sTCP:LISTEN) and run the tests again.\n`,
    )
    process.exit(1)
  }
}

/** Runs a child in the foreground of this launcher; its exit ends the launcher. Signals are forwarded. */
export function run(command, args, options) {
  const child = spawn(command, args, { stdio: 'inherit', ...options })
  for (const signal of ['SIGINT', 'SIGTERM', 'SIGHUP']) process.on(signal, () => child.kill(signal))
  child.on('exit', (code, signal) => process.exit(code ?? (signal ? 1 : 0)))
  child.on('error', (error) => {
    console.error(`[e2e] Could not start ${command}: ${error.message}`)
    process.exit(1)
  })
  return child
}

/** Runs a command to completion and returns its exit code (output is shown). */
export function runToEnd(command, args, options) {
  return new Promise((resolve, reject) => {
    const child = spawn(command, args, { stdio: 'inherit', ...options })
    child.on('error', reject)
    child.on('exit', (code) => resolve(code ?? 1))
  })
}
EOF
cat > support/start-api.mjs <<'EOF'
// Starts the FastAPI backend for the e2e run on port 9281 with a fresh SQLite database.
// (Playwright starts webServers BEFORE global setup, so the database and upload folder are
// wiped here, before the API creates and seeds its tables.)
import fs from 'node:fs'
import { API_PORT, BACKEND_DIR, DB_PATH, TMP_DIR, UPLOAD_DIR, backendEnv } from './env.mjs'
import { assertPortFree, run } from './launch.mjs'

await assertPortFree(API_PORT, 'e2e API')

for (const suffix of ['', '-wal', '-shm', '-journal']) fs.rmSync(`${DB_PATH}${suffix}`, { force: true })
fs.rmSync(UPLOAD_DIR, { recursive: true, force: true })
fs.mkdirSync(UPLOAD_DIR, { recursive: true })
fs.mkdirSync(TMP_DIR, { recursive: true })

console.log(`[e2e] API on http://localhost:${API_PORT}, database ${DB_PATH} (fake LLM, fake submission adapter)`)
run('uv', ['run', '--frozen', 'uvicorn', 'app.main:app', '--host', '127.0.0.1', '--port', String(API_PORT)], {
  cwd: BACKEND_DIR,
  env: backendEnv(),
})
EOF
cat > support/start-web.mjs <<'EOF'
// Builds the Nuxt frontend once (incrementally) and serves the production build on port 9280.
//
// The build happens in a private copy (.build/web) so it never touches frontend/.output, which
// other dev servers may be serving, and so a half-edited source tree is snapshotted once.
// It is rebuilt only when the frontend sources changed (rsync sees a difference), when the
// build is missing, or when E2E_REBUILD=1.
import { spawnSync } from 'node:child_process'
import fs from 'node:fs'
import path from 'node:path'
import { API_URL, BUILD_DIR, FRONTEND_DIR, WEB_PORT, webEnv } from './env.mjs'
import { assertPortFree, run, runToEnd } from './launch.mjs'

await assertPortFree(WEB_PORT, 'e2e web')

fs.mkdirSync(BUILD_DIR, { recursive: true })
const sync = spawnSync(
  'rsync',
  [
    '-a', '--delete', '--itemize-changes',
    '--exclude', 'node_modules', '--exclude', '.nuxt', '--exclude', '.output',
    '--exclude', '.env*', '--exclude', 'tests', '--exclude', '.DS_Store',
    `${FRONTEND_DIR}/`, `${BUILD_DIR}/`,
  ],
  { encoding: 'utf8' },
)
if (sync.status !== 0) {
  console.error(`[e2e] rsync failed (is rsync installed?): ${sync.stderr}`)
  process.exit(1)
}
const changed = sync.stdout.trim().length > 0

const nodeModules = path.join(BUILD_DIR, 'node_modules')
if (!fs.existsSync(nodeModules)) fs.symlinkSync(path.join(FRONTEND_DIR, 'node_modules'), nodeModules)

const entry = path.join(BUILD_DIR, '.output', 'server', 'index.mjs')
if (changed || !fs.existsSync(entry) || process.env.E2E_REBUILD === '1') {
  console.log('[e2e] Building the frontend (first run or sources changed; takes about a minute)...')
  fs.rmSync(path.join(BUILD_DIR, '.output'), { recursive: true, force: true })
  // No --dotenv: the repo-root .env must not influence the test build.
  const code = await runToEnd(path.join(nodeModules, '.bin', 'nuxt'), ['build'], {
    cwd: BUILD_DIR,
    env: { ...webEnv(), NUXT_TELEMETRY_DISABLED: '1' },
  })
  if (code !== 0) {
    console.error('[e2e] Frontend build failed.')
    process.exit(code)
  }
}
else {
  console.log('[e2e] Frontend sources unchanged: reusing the previous build (E2E_REBUILD=1 forces a rebuild).')
}

console.log(`[e2e] Web on http://localhost:${WEB_PORT} (API ${API_URL})`)
run('node', [entry], { cwd: BUILD_DIR, env: webEnv() })
EOF
