import { execFileSync } from 'node:child_process'
import { DB_PATH } from './env.mjs'

export interface AuditRow {
  id: number
  actor_user_id: number | null
  entity_type: string
  entity_id: number | null
  event_type: string
  from_status: string | null
  to_status: string | null
