      timeout: 60_000,
    })
  }
  catch (error) {
    const e = error as { stdout?: string, stderr?: string, message: string }
    throw new Error(`resetData failed: ${e.message}\n${e.stdout ?? ''}\n${e.stderr ?? ''}`)
  }
}
